 using Microsoft.EntityFrameworkCore;
 class MigrationRunner
 {
     // EF Core 9 breaking change: Migrate() now manages its own transactions internally
     // and throws if called inside a user-started transaction.
     void ApplyMigrations(AppDbContext db)
     {
         var strategy = db.Database.CreateExecutionStrategy();
         strategy.Execute(() =>
         {
             db.Database.Migrate();
         });
     }
 }
